import { update, save, getEnumList } from "@/api/i6000/enum";
export default {
  name: "pzsxAddEdit",
  props: ['fromValue', 'isShow', 'type'],
  data: function data() {
    return {
      submitParams: {},
      rules: {
        enumId: [{
          required: true,
          message: '枚举ID不能为空',
          trigger: 'blur'
        }],
        enumName: [{
          required: true,
          message: '枚举数据名称不能为空',
          trigger: 'blur'
        }],
        enumvalCode: [{
          required: true,
          message: '枚举项编码不能为空',
          trigger: 'blur'
        }],
        enumvalName: [{
          required: true,
          message: '枚举项名称不能为空',
          trigger: 'blur'
        }]
      },
      saveLoading: false,
      enumList: null
    };
  },
  mounted: function mounted() {
    this.initDict();
    if (this.type == 'edit') {
      this.submitParams = JSON.parse(JSON.stringify(this.fromValue));
    }
  },
  methods: {
    initDict: function initDict() {
      var _this = this;
      getEnumList().then(function (res) {
        _this.enumList = res.data;
      });
    },
    submit: function submit() {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this2.type == 'add') {
            _this2.saveLoading = true;
            save(_this2.submitParams).then(function (res) {
              _this2.saveLoading = false;
              _this2.$message.success('添加成功');
              _this2.$emit("close");
              _this2.$emit("refreshData");
            }).finally(function () {
              _this2.saveLoading = false;
            });
          } else if (_this2.type == 'edit') {
            _this2.saveLoading = true;
            update(_this2.submitParams).then(function (res) {
              _this2.saveLoading = false;
              _this2.$message.success('修改成功');
              _this2.$emit("close");
              _this2.$emit("refreshData");
            }).finally(function () {
              _this2.saveLoading = false;
            });
          }
        }
      });
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
